def _validate_braces(self):
    """Validate that all braces are properly matched."""
    # Track brace nesting - only count { and } that start/end groups
    # {{ and }} are escaped, so we need to handle them specially
    i = 0
    while i < len(self._format):
        if self._format[i:i+2] == '{{':
            i += 2
            continue
        elif self._format[i:i+2] == '}}':
            i += 2
            continue
        elif self._format[i] == '{':
            # Find matching closing brace
            depth = 1
            j = i + 1
            while j < len(self._format) and depth > 0:
                if self._format[j:j+2] == '{{':
                    j += 2
                    continue
                elif self._format[j:j+2] == '}}':
                    j += 2
                    continue
                elif self._format[j] == '{':
                    depth += 1
                elif self._format[j] == '}':
                    depth -= 1
                j += 1
            if depth != 0:
                raise ValueError('unmatched left brace in format')
            i = j
        elif self._format[i] == '}':
            raise ValueError('unmatched right brace in format')
        else:
            i += 1

